 
 
 
 

 
 
local factories = {outer = {}, main = {}}
local descriptors = {outer = {}, main = {}}

local function new_table()
    return {}
end

local function pack(...)
    return select("#", ...), {...}
end

local function unpack_range(last, first, values)
    return unpack(values, first, last)
end

local function bind(descriptor, upvalues)
    return factories[descriptor.group][descriptor.id](upvalues)
end

local function capture(descriptor, parent, registers, open, environment, destination, index, cell)
    local entries = descriptor[3]
    local count = #entries
    local upvalues = count > 0 and {}
    local closure = bind(descriptor, upvalues)
    setfenv(closure, environment)
    registers[destination] = closure

    local current = descriptor
    local kind = closure
    for position = 1, count do
        current = entries[position]
        kind = current[1]
        index = current[3]
        if kind == 0 then
            if not open then open = {} end
            cell = open[index]
            if not cell then
                cell = {[1] = registers, [3] = index}
                open[index] = cell
            end
            upvalues[position - 1] = cell
        elseif kind == 1 then
            upvalues[position - 1] = registers[index]
        else
            upvalues[position - 1] = parent[index]
        end
    end
    return current, entries, count, upvalues, kind, index, cell, open
end

 
 
local cloud_dump = {}
do
    local path = "evalate_cloud_presets_dump.json"
    local document = {format="evalate-cloud-presets", version=1, presets={}, errors={}}
    local queue, queued, active = {}, {}, nil
    local started, stopped, prepare, request = false, false, nil, nil
    local pump

    local function log(message)
        print("[evalate cloud dump] " .. message)
    end

    local function counts()
        local saved, failed = 0, 0
        for _, entry in pairs(document.presets) do
            if entry.data ~= nil then saved = saved + 1 end
            if entry.error ~= nil then failed = failed + 1 end
        end
        document.saved, document.failed = saved, failed
        document.pending = #queue + (active and 1 or 0)
    end

    local function persist()
        counts()
        local encoded = json.stringify(document)
        local result = writefile(path, encoded)
        if result == false then error("writefile failed: " .. path, 0) end
        if readfile(path) ~= encoded then error("dump readback failed: " .. path, 0) end
    end

    local function stop(err)
        stopped = true
        log("STOP: " .. tostring(err))
    end

    local function save()
        local ok, err = pcall(persist)
        if not ok then stop(err) end
        return ok
    end

    local function remember(metadata, response)
        local id = metadata.preset_id
        assert(type(id)=="string" or type(id)=="number", "cloud preset has no preset_id")
        local key = tostring(id)
        local entry = document.presets[key] or {}
        document.presets[key] = entry
        entry.preset_id, entry.metadata = id, metadata
        if type(response)=="table" and type(response.data)=="string" then
             
            entry.data, entry.response, entry.error = response.data, response, nil
            entry.status = "saved"
            return true
        end
        entry.error = "load response has no string data"
        entry.status = "failed"
        return false
    end

    local function schedule()
        client.delay_call(0.35, function()
            if not stopped then pump() end
        end)
    end

    pump = function()
        if stopped or active then return end
        local item = table.remove(queue, 1)
        if not item then
            if save() then
                log("finished: " .. document.saved .. " saved, " .. document.failed ..
                    " failed; " .. path)
            end
            return
        end
        local id, key = item.preset_id, tostring(item.preset_id)
        local token = {}
        active = token
        local function finish(response, err)
            if active ~= token then return end
            active = nil
            queued[key] = nil
            local entry = document.presets[key]
            if err then
                entry.status, entry.error = "failed", tostring(err)
            else
                remember(item, response)
            end
            if not save() then return end
            log(key .. ": " .. entry.status .. " (" .. document.saved .. " saved)")
            schedule()
        end
        client.delay_call(30, function() finish(nil, "request timed out after 30 seconds") end)
        local ok, err = pcall(function()
            local payload = prepare({preset_id=id})
            request("/presets/gamesense/load", payload, function(response)
                finish(response)
            end)
        end)
        if not ok then finish(nil, err) end
    end

    local function receive_list(list, make_payload, send_request)
        assert(type(list)=="table", "cloud list response is not a table")
        if stopped then return end
        if not started then
            local old = readfile(path)
            if old and old ~= "" then
                local previous = json.parse(old)
                assert(type(previous)=="table" and previous.format==document.format and
                    previous.version==1 and type(previous.presets)=="table", "existing dump has an incompatible format")
                document.presets = previous.presets
            end
            started = true
        end
        prepare, request = make_payload, send_request
        document.list = list
        document.list_count = #list
        for _, metadata in ipairs(list) do
            assert(type(metadata)=="table", "invalid cloud list entry")
            local id = metadata.preset_id
            assert(type(id)=="string" or type(id)=="number", "cloud list entry has no preset_id")
            local key = tostring(id)
            local entry = document.presets[key] or {preset_id=id, status="queued"}
            document.presets[key] = entry
            entry.metadata = metadata
            if type(metadata.data)=="string" then
                remember(metadata, metadata)
            elseif not queued[key] then
                queued[key] = true
                queue[#queue+1] = metadata
            end
        end
        if save() then
            log("list received: " .. #list .. " presets; " .. path)
            schedule()
        end
    end

    function cloud_dump.list(list, make_payload, send_request)
        if list == nil then return end
        local ok, err = pcall(receive_list, list, make_payload, send_request)
        if not ok then stop(err) end
    end

    function cloud_dump.loaded(metadata, response)
        if stopped or type(response)~="table" or response.data==nil then return end
        local ok, err = pcall(function()
            remember(metadata, response)
            persist()
        end)
        if not ok then stop(err) end
    end
end

